	async getRemoteHubApi(): Promise<RemoteHubApi | undefined> {
		try {
			const extension =
				extensions.getExtension<RemoteHubApi>('GitHub.remotehub') ??
				extensions.getExtension<RemoteHubApi>('GitHub.remotehub-insiders');
			if (extension != null) {
				const api = extension.isActive ? extension.exports : await extension.activate();
				return api;
			}
		} catch {}

		return undefined;
	}

	dispose() {
		this._disposable.dispose();
	}

	private readonly _repositories = new Map<string, Metadata>();

	private async onWorkspaceFoldersChanged(e?: WorkspaceFoldersChangeEvent) {
		let initializing = false;
		if (e == null) {
			initializing = true;
			e = {
				added: workspace.workspaceFolders ?? [],
				removed: [],
			};

			Logger.log(`Starting repository search in ${e.added.length} folders`);
		}

		const virtualApi = await this.getRemoteHubApi();

		for (const f of e.added) {
			const { scheme } = f.uri;
			if (scheme !== DocumentSchemes.VirtualFile) continue;

			const metadata = await virtualApi?.getMetadata(f.uri);
			if (metadata?.provider.id === 'github') {
				this._repositories.set(f.uri.toString(), metadata);
			}
		}

		for (const f of e.removed) {
			const { scheme } = f.uri;
			if (scheme !== DocumentSchemes.VirtualFile) continue;

			const metadata = await virtualApi?.getMetadata(f.uri);
			if (metadata?.provider.id === 'github') {
				this._repositories.delete(f.uri.toString());
			}
		}

		await this.updateContext();

		if (!initializing) {
			// Defer the event trigger enough to let everything unwind
			setImmediate(() => this.fireRepositoriesChanged());
		}
	}

